<template>
  <main class="admission-workspace">
    <header><div><p class="eyebrow">LOCAL ADMISSION</p><h1>本地入库</h1><p>从等待区选择多位博主，集中核对一次，后台依次接纳。</p></div><RouterLink to="/archive-catalog">博主库</RouterLink></header>
    <ol class="steps" aria-label="入库步骤"><li :class="{current:!collection}">1 选择博主与目录</li><li :class="{current:collection?.state==='draft'}">2 集中核对</li><li :class="{current:collection&&collection.state!=='draft'}">3 后台结果</li></ol>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <details class="panel history"><summary>最近批次与历史记录</summary><p v-if="!recent?.items.length">尚无多博主批次；单博主历史记录仍在对应博主的本地导入页。</p><ul><li v-for="entry in recent?.items" :key="entry.id"><button :disabled="busy" @click="openCollection(entry.id)">{{ time(entry.createdAt) }} · {{ entry.totals.creators }} 位博主 / {{ entry.totals.total }} 目录 · {{ stateLabel(entry.state) }}</button></li></ul><div class="toolbar"><button :disabled="busy" @click="loadRecent(recent?.page??1)">刷新记录</button><button v-if="recent&&recent.page>1" :disabled="busy" @click="loadRecent(recent.page-1)">上一页记录</button><button v-if="recent&&recent.page*recent.pageSize<recent.total" :disabled="busy" @click="loadRecent(recent.page+1)">下一页记录</button></div></details>

    <section v-if="!collection" class="panel" aria-label="选择博主与目录">
      <div class="heading"><h2>选择这次要收录的范围</h2><button :disabled="busy||loading" @click="loadWorkspace">刷新等待区</button></div>
      <p class="hint">这里只列等待区，按选择的作品目录保留原名与内部结构。合集、按月份或类型分层等复杂目录先核对作品边界，不自动拆分或合并。</p>
      <details class="settings"><summary>路径与高级设置</summary><dl v-if="workspace"><dt>等待区</dt><dd>{{ workspace.waitingRoot||'未设置' }}</dd><dt>正式图库</dt><dd>{{ workspace.galleryRoot }}</dd></dl><form @submit.prevent="saveSettings"><label>已解压等待区<input v-model="waitingRoot" required /></label><button :disabled="busy">保存等待区</button></form><p class="hint">压缩包仍使用 Stage3；本页只接纳已分套的目录。</p></details>
      <input v-model="filter" class="filter" type="search" placeholder="筛选等待区名称或已匹配博主" aria-label="筛选等待区博主" />
      <p v-if="loading" role="status">读取等待区…</p><p v-else-if="!visibleFolders.length">当前没有匹配的等待区目录。</p>
      <article v-for="folder in visibleFolders" :key="folder.name" class="folder" :data-folder="folder.name">
        <div class="heading"><label class="check folder-name"><input type="checkbox" :checked="choices[folder.name]?.selected" :disabled="busy||!folder.selectable||!choices[folder.name]?.creator" @change="toggleFolder(folder.name,($event.target as HTMLInputElement).checked)" /><strong>{{ folder.name }}</strong></label><span class="identity">{{ choices[folder.name]?.creator?.name||'需选择规范博主' }}</span></div>
        <p v-if="folder.reason" class="warning">{{ folder.reason }}</p>
        <p class="hint">{{ folder.matches.length===1?(folder.matches[0].matchKind==='alias'?'已登记别名匹配':'规范名称匹配'):folder.matches.length>1?'多个身份候选，需明确选择':'未自动对应，不会创建新博主' }}</p>
        <details :open="!choices[folder.name]?.creator"><summary>核对 / 更换博主身份</summary><div class="toolbar"><button v-for="match in folder.matches" :key="match.creatorId" :disabled="busy" @click="setCreator(folder.name,{id:match.creatorId,name:match.creatorName,aliases:[]})">{{ match.creatorName }} · {{ match.matchedName }}</button></div><AdmissionCreatorPicker @select="setCreator(folder.name,$event)" /></details>
        <template v-if="choices[folder.name]?.selected"><p v-if="choices[folder.name].loading" role="status">读取本博主作品目录…</p><p v-if="choices[folder.name].error" class="error">{{ choices[folder.name].error }}</p>
          <div class="toolbar"><label class="check"><input type="checkbox" :checked="allSelected(folder.name)" :disabled="busy||choices[folder.name].loading" @change="selectFolderDirectories(folder.name,($event.target as HTMLInputElement).checked)" />选择全部可用作品目录</label><span>{{ choices[folder.name].directories.length }} 个已选</span></div>
          <div class="directory-grid"><label v-for="directory in choices[folder.name].available" :key="directory.name" class="check"><input v-model="choices[folder.name].directories" type="checkbox" :value="directory.name" :disabled="busy||!directory.selectable" /><span>{{ directory.name }}<small v-if="directory.reason">{{ directory.reason }}</small></span></label></div>
          <AdmissionSourcePicker v-if="choices[folder.name].creator" v-model="choices[folder.name].sourceEvidenceId" :creator-id="choices[folder.name].creator!.id" />
        </template>
      </article>
      <div class="stage-actions"><div><strong>{{ chosenFolders.length }} 位博主 · {{ directoryCount }} 个目录</strong><p class="hint">复制 / 解压完成后再进入核对；此步只生成预览，不移动文件。</p></div><button class="primary" data-test="collection-preview" :disabled="busy||!directoryCount||!!scopeError" @click="preview">{{ busy?'生成预览中…':'下一步 · 集中核对' }}</button></div><p v-if="scopeError" class="error">{{ scopeError }}</p>
    </section>

    <template v-if="collection">
      <section class="panel overview"><div class="heading"><h2>{{ stateLabel(collection.state) }}</h2><div class="toolbar"><button :disabled="busy" @click="refreshCollection()">刷新状态</button><button v-if="!active" :disabled="busy" @click="startNew">选择新批次</button></div></div><p>{{ collection.totals.creators }} 位博主 · {{ collection.totals.total }} 个目录 · {{ collection.totals.completed }} 已完成<span v-if="collection.totals.failedCreators"> · {{ collection.totals.failedCreators }} 位需处理</span></p><p v-if="active" role="status">后台按博主串行处理。关闭页面不取消；刷新或重新打开从最近批次查看，不会自动运行其他历史任务。</p><p v-if="collection.error" class="error">{{ collection.error }}</p><details><summary>技术详情</summary><p>{{ collection.id }} · {{ collection.updatedAt }}</p></details></section>

      <section v-if="collection.state==='draft'" class="panel" aria-label="多博主集中核对">
        <div class="heading"><div><h2>核对作品身份与文件范围</h2><p class="hint">首次核对已预选可直接入库的新作品，候选对应、同套副本和复杂目录仍需判断。预选不等于执行，提交前可逐项调整。</p></div><button data-test="collection-select-safe" :disabled="locked" @click="selectSafe()">补选可直接入库的作品</button></div>
        <p class="hint">刷新状态只读取当前批次，不会重新检查磁盘或覆盖已有选择。若已整理、增删或改名目录，请用“选择新批次”重新预览；本按钮只补选当前预览中无冲突且仍暂缓的新作品。</p>
        <AdmissionAcquisitionPolicy :retry="!!pending" />
        <AdmissionAdsPicker :entries="allEntries" :locked="locked" @change="adsConfirmed=false" />
        <div class="creator-tabs" role="tablist" aria-label="按博主核对"><button v-for="entry in collection.batches" :key="entry.id" role="tab" :aria-selected="activeBatchId===entry.id" @click="activeBatchId=entry.id;page=1">{{ entry.creatorName }} <small>{{ contexts[entry.id]?.items.length??entry.totals.total }} 目录</small></button></div>
        <div v-if="currentContext"><div class="toolbar"><label>查看分组<select v-model="group"><option value="all">全部目录</option><option v-for="(name,key) in admissionGroups" :key="key" :value="key">{{ key }} · {{ name }}</option></select></label><span>{{ currentContext.batch.creatorName }} · {{ currentContext.batch.parent }}</span></div><p v-if="itemsLoading" role="status">读取目录摘要…</p>
          <AdmissionItemEditor v-for="item in visibleItems" :key="`${activeBatchId}:${item.key}`" v-model="currentContext.actions[item.key]" :item="item" :creator-id="currentContext.batch.creatorId" :peers="entriesFor(currentContext)" :selected-work="currentContext.works[item.key]" :locked="locked" :accept-existing-version="acceptsExistingVersion(currentContext.batch.id)" @select-work="currentContext.works[item.key]=$event" @change="adsConfirmed=false" />
          <div class="pagination"><button :disabled="page<=1" @click="page--">上一页目录</button><span>第 {{ page }} / {{ Math.max(1,Math.ceil(filteredItems.length/20)) }} 页 · {{ filteredItems.length }} 目录</span><button :disabled="page*20>=filteredItems.length" @click="page++">下一页目录</button></div>
        </div>
        <p v-if="pending" class="warning">执行回执尚未确认。原范围与选择已保留，只能核对并重试原请求，不会再次建立计划。</p>
        <div class="stage-actions"><strong>{{ selectedCount }} 接纳 · {{ skippedCount }} 跳过 · {{ deferredCount }} 暂缓</strong><button class="primary" data-test="collection-confirm" :disabled="busy||itemsLoading||!allEntries.length" @click="showConfirm=true">{{ pending?'核对并重试原提交':'核对全部并确认' }}</button></div>
      </section>

      <section v-else class="panel" aria-label="多博主后台结果"><h2>按博主查看结果</h2><article v-for="entry in collection.batches" :key="entry.id" class="result"><div class="heading"><h3>{{ entry.creatorName }}</h3><span>{{ batchStateLabel(entry.state) }}</span></div><p>{{ entry.totals.completed }} 已完成 · {{ entry.totals.skipped }} 跳过 · {{ entry.totals.deferred }} 暂缓</p><p v-if="entry.error" class="error">{{ entry.error }}</p><details><summary>目录明细与处理入口</summary><ul><li v-for="item in contexts[entry.id]?.items" :key="item.key"><strong>{{ item.sourceRelativePath }}</strong><span>{{ item.state==='completed'?'完成':item.state==='skip'?'跳过，等待区保留':item.state==='defer'?'暂缓，等待区保留':item.state }}</span><p v-if="item.lastError" class="error">{{ item.lastError }}</p><RouterLink v-if="item.postId" :to="{name:'canonical-work-gallery',params:{creatorId:entry.creatorId,postId:item.postId}}">查看图集</RouterLink><RouterLink v-if="entry.planId&&item.lastError&&item.state!=='completed'" :to="{name:'local-review',query:{kind:'admission',planId:entry.planId,itemKey:item.key,creatorId:entry.creatorId}}">查看并处理</RouterLink></li></ul></details></article><div v-if="['partial','interrupted'].includes(collection.state)" class="stage-actions"><div><p>已完成的博主不会重跑；先处理具体失败原因，再继续原集合未完成项。</p><p class="hint">尚未移动但源文件已变化的目录：使用“选择新批次”重新预览仍在等待区的目录，不能修改或重放原确认计划。已经移动的项目按原检查点处理，必要时进入“查看并处理”。</p></div><button :disabled="busy" @click="showResume=true">核对后继续本批</button></div></section>
    </template>

    <div v-if="showConfirm&&collection" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="确认多博主接纳"><h2>一次确认本批全部范围</h2><p>{{ collection.totals.creators }} 位博主 · {{ selectedCount }} 个接纳目录 · {{ skippedCount }} 跳过 · {{ deferredCount }} 暂缓。</p><div class="confirmation-list"><details v-for="entry in collection.batches" :key="entry.id" open><summary>{{ entry.creatorName }} · {{ entry.parent }}</summary><ul><li v-for="pair in contexts[entry.id]?entriesFor(contexts[entry.id]):[]" :key="pair.item.key"><strong>{{ pair.item.sourceRelativePath }}</strong><span>{{ admissionActionLabels[pair.action.action] }}<template v-if="contexts[entry.id].works[pair.item.key]"> → {{ contexts[entry.id].works[pair.item.key].title }}</template><template v-else-if="pair.action.action==='existing'&&pair.action.workId"> → 作品 #{{ pair.action.workId }}（展示资料未缓存）</template><template v-if="pair.action.sameAsKey"> → {{ contexts[entry.id].items.find(item=>item.key===pair.action.sameAsKey)?.sourceRelativePath }}</template></span><small v-if="isAdmissionSelected(pair.action)">{{ pair.item.targetPath }}</small><small v-if="pair.action.primary">使用本目录为主副本，其他副本保留</small><small v-for="ad in pair.action.approvedAds" :key="ad">广告可恢复移出：{{ ad }}</small></li></ul></details></div><AdmissionAcquisitionPolicy :retry="!!pending" /><p>跳过 / 暂缓不删除，目标已存在不覆盖。</p><p v-if="selectionError" class="error">{{ selectionError }}</p><p v-if="error" role="alert" class="error">{{ error }}</p><label class="check"><input v-model="confirmed" type="checkbox" />确认上述所有博主、目录及作品选择；当前文件没有继续写入</label><label v-if="adsCount" class="check warning"><input v-model="adsConfirmed" type="checkbox" />另行批准列出的 {{ adsCount }} 个明确广告文件可恢复移出，其他附件保留</label><div class="dialog-actions"><button :disabled="busy" @click="showConfirm=false">返回核对</button><button class="primary" data-test="collection-execute" :disabled="busy||!confirmed||(adsCount>0&&!adsConfirmed)||!!selectionError" @click="execute">{{ busy?'提交中…':pending?'重试原请求':'确认并后台依次执行' }}</button></div></section></div>
    <div v-if="showResume&&collection" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="继续多博主原批次"><h2>继续本批未完成项</h2><p>复用已确认计划和检查点，核对实际文件后继续。已完成项不再移动，不自动恢复其他集合或历史任务。</p><div class="dialog-actions"><button :disabled="busy" @click="showResume=false">取消</button><button class="primary" :disabled="busy" @click="resume">确认继续原批次</button></div></section></div>
  </main>
</template>

<script setup lang="ts">
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue';
import { RouterLink,useRoute,useRouter } from 'vue-router';
import AdmissionCreatorPicker from '../components/AdmissionCreatorPicker.vue';
import AdmissionSourcePicker from '../components/AdmissionSourcePicker.vue';
import AdmissionItemEditor from '../components/AdmissionItemEditor.vue';
import AdmissionAcquisitionPolicy from '../components/AdmissionAcquisitionPolicy.vue';
import AdmissionAdsPicker from '../components/AdmissionAdsPicker.vue';
import * as api from '../api/local-admission';
import { RequestError } from '../api/http';
import { clearAdmissionDraft,lastAdmissionCollection,rememberAdmissionCollection,restoreAdmissionDraft,saveAdmissionDraft } from '../utils/admission-navigation';
import { admissionAction,admissionActionLabels,admissionGroups,admissionPayload,isAdmissionSelected,validateAdmissionSelection,type AdmissionEntry } from '../utils/admission-ui';
import type { AdmissionAction,AdmissionBatch,AdmissionCollection,AdmissionCollectionExecuteInput,AdmissionCreator,AdmissionDirectory,AdmissionItem,AdmissionPage,AdmissionWork,AdmissionWorkspace } from '../types/local-admission';

interface FolderChoice {selected:boolean;creator:AdmissionCreator|null;available:AdmissionDirectory[];directories:string[];sourceEvidenceId:number|null;loading:boolean;error:string;request:number}
interface BatchContext {batch:AdmissionCollection['batches'][number];items:AdmissionItem[];actions:Record<string,AdmissionAction>;works:Record<string,AdmissionWork>}
const route=useRoute(),router=useRouter(),workspace=ref<AdmissionWorkspace|null>(null),waitingRoot=ref(''),choices=reactive<Record<string,FolderChoice>>({}),filter=ref(''),loading=ref(false),busy=ref(false),itemsLoading=ref(false),error=ref(''),notice=ref('');
const collection=ref<AdmissionCollection|null>(null),contexts=reactive<Record<string,BatchContext>>({}),recent=ref<AdmissionPage<AdmissionCollection>|null>(null),activeBatchId=ref(''),page=ref(1),group=ref('all'),showConfirm=ref(false),confirmed=ref(false),adsConfirmed=ref(false),showResume=ref(false),pending=ref<AdmissionCollectionExecuteInput|null>(null);
let generation=0,disposed=false,startingNew=false,timer:ReturnType<typeof setTimeout>|undefined,pollFailures=0;
const active=computed(()=>!!collection.value&&['queued','running'].includes(collection.value.state));
const locked=computed(()=>busy.value||itemsLoading.value||!!pending.value||collection.value?.state!=='draft');
const visibleFolders=computed(()=>workspace.value?.items.filter(folder=>`${folder.name} ${folder.matches.map(match=>match.creatorName).join(' ')}`.toLowerCase().includes(filter.value.trim().toLowerCase()))??[]);
const chosenFolders=computed(()=>Object.entries(choices).filter(([,value])=>value.selected));
const directoryCount=computed(()=>chosenFolders.value.reduce((sum,[,value])=>sum+value.directories.length,0));
const scopeError=computed(()=>{if(chosenFolders.value.length>100)return '每批最多选择100位博主，请分批处理。';const ids=new Set<number>();for(const [name,value] of chosenFolders.value){if(!value.creator)return '请先明确每个目录的规范博主。';if(ids.has(value.creator.id))return `“${value.creator.name}”对应多个等待区父目录，请分批核对；不会自动混合。`;ids.add(value.creator.id);if(value.loading)return '正在读取所选博主的目录。';if(value.error)return '部分目录读取失败，请重新勾选读取。';if(!value.directories.length)return `“${name}”没有选择作品目录，请选择目录或取消勾选该博主。`;}return '';});
const currentContext=computed(()=>contexts[activeBatchId.value]);
const entriesFor=(context:BatchContext):AdmissionEntry[]=>context.items.map(item=>({item,action:context.actions[item.key]}));
const draftEntries=()=>Object.values(contexts).flatMap(context=>entriesFor(context).map(entry=>({...entry,batchId:context.batch.id,creatorId:context.batch.creatorId,work:context.works[entry.item.key]})));
function saveDraft(){if(collection.value?.state==='draft'&&!pending.value&&!itemsLoading.value)saveAdmissionDraft(collection.value.id,draftEntries());}
const allEntries=computed(()=>collection.value?.batches.flatMap(batch=>contexts[batch.id]?entriesFor(contexts[batch.id]):[])??[]);
const selectedCount=computed(()=>allEntries.value.filter(entry=>isAdmissionSelected(entry.action)).length),skippedCount=computed(()=>allEntries.value.filter(entry=>entry.action.action==='skip').length),deferredCount=computed(()=>allEntries.value.filter(entry=>entry.action.action==='defer').length);
const adsCount=computed(()=>allEntries.value.reduce((sum,entry)=>sum+(isAdmissionSelected(entry.action)?entry.action.approvedAds?.length??0:0),0));
const filteredItems=computed(()=>currentContext.value?.items.filter(item=>group.value==='all'||item.group===group.value)??[]),visibleItems=computed(()=>filteredItems.value.slice((page.value-1)*20,page.value*20));
const selectionError=computed(()=>{for(const entry of collection.value?.batches??[]){const context=contexts[entry.id];if(!context)return '目录摘要尚未读取完成。';const message=validateAdmissionSelection(entriesFor(context));if(message)return `${entry.creatorName}：${message}`;}return '';});
const stateLabel=(state:AdmissionCollection['state'])=>({draft:'预览草稿 · 未执行',queued:'等待后台执行',running:'后台处理中',completed:'本批处理完成',partial:'部分完成 · 有项目需处理',interrupted:'中断 · 原批次保留'}[state]);
const batchStateLabel=(state:AdmissionBatch['state'])=>({draft:'待确认',queued:'等待处理',running:'处理中',completed:'完成',needs_review:'需要查看',interrupted:'中断',failed:'失败'}[state]);
const time=(value:string)=>new Date(value).toLocaleString();
const storageKey=(id:string)=>`cosgallery:admission:collection:${id}`;
const definitive=(cause:unknown)=>cause instanceof RequestError&&[400,403,404,409,413,422].includes(cause.status);
function acceptsExistingVersion(batchId:string){return pending.value?.batches.find(entry=>entry.batchId===batchId)?.acceptExistingVersion??true;}
function setPending(value:AdmissionCollectionExecuteInput|null){pending.value=value;if(!collection.value)return;try{if(value)localStorage.setItem(storageKey(collection.value.id),JSON.stringify(value));else localStorage.removeItem(storageKey(collection.value.id));}catch{notice.value='浏览器无法保存重试凭据，请保留此页直至确认回执；服务端批次仍会保存。';}}
function restorePending(){if(!collection.value)return;try{const value:unknown=JSON.parse(localStorage.getItem(storageKey(collection.value.id))||'null');if(!value||typeof value!=='object'||!('requestKey'in value)||typeof value.requestKey!=='string'||!('confirmed'in value)||value.confirmed!==true||!('batches'in value)||!Array.isArray(value.batches))return;for(const entry of value.batches){if(!entry||typeof entry!=='object'||typeof entry.batchId!=='string'||!contexts[entry.batchId]||typeof entry.acceptExistingVersion!=='boolean'||!Array.isArray(entry.actions))return;for(const action of entry.actions)if(!action||typeof action!=='object'||typeof action.key!=='string'||!contexts[entry.batchId].actions[action.key]||!['new','existing','same-as','skip','defer'].includes(action.action))return;}const restored=value as AdmissionCollectionExecuteInput;pending.value=restored;for(const entry of restored.batches)for(const action of entry.actions){const context=contexts[entry.batchId];context.actions[action.key]=action;const old=context.works[action.key];delete context.works[action.key];if(action.action==='existing'){const match=old?.workId===action.workId?old:context.items.find(item=>item.key===action.key)?.candidates.find(work=>work.workId===action.workId);if(match)context.works[action.key]=match;}}}catch{/* Local retry data does not authorize server writes. */}}
async function loadWorkspace(){const current=generation;loading.value=true;error.value='';try{const result=await api.fetchAdmissionWorkspace();if(current!==generation||disposed)return;workspace.value=result;waitingRoot.value=result.waitingRoot;for(const key of Object.keys(choices))delete choices[key];for(const folder of result.items){const match=folder.matches.length===1?folder.matches[0]:null;choices[folder.name]={selected:false,creator:match?{id:match.creatorId,name:match.creatorName,aliases:[]}:null,available:[],directories:[],sourceEvidenceId:null,loading:false,error:'',request:0};}}catch(cause){if(current===generation)error.value=cause instanceof Error?cause.message:'等待区读取失败';}finally{if(current===generation)loading.value=false;}}
function setCreator(name:string,creator:AdmissionCreator){if(busy.value)return;const choice=choices[name];if(!choice)return;choice.request++;choice.creator=creator;choice.selected=false;choice.directories=[];choice.available=[];choice.sourceEvidenceId=null;choice.loading=false;choice.error='';}
async function toggleFolder(name:string,selected:boolean){if(busy.value)return;const choice=choices[name];if(!choice?.creator)return;choice.selected=selected;const request=++choice.request,current=generation;if(!selected){choice.loading=false;return;}choice.loading=true;choice.error='';try{const result=await api.fetchAdmissionDirectories(choice.creator.id,name);if(current!==generation||request!==choice.request||disposed)return;choice.available=result.items;choice.directories=result.items.filter(item=>item.selectable).map(item=>item.name);}catch(cause){if(current===generation&&request===choice.request)choice.error=cause instanceof Error?cause.message:'目录读取失败';}finally{if(current===generation&&request===choice.request)choice.loading=false;}}
function allSelected(name:string){const value=choices[name],available=value?.available.filter(item=>item.selectable)??[];return !!available.length&&available.every(item=>value.directories.includes(item.name));}
function selectFolderDirectories(name:string,selected:boolean){if(busy.value)return;const choice=choices[name];choice.directories=selected?choice.available.filter(item=>item.selectable).map(item=>item.name):[];}
async function saveSettings(){if(busy.value)return;const current=generation;busy.value=true;error.value='';try{await api.saveAdmissionSettings(waitingRoot.value);if(current===generation&&!disposed)await loadWorkspace();}catch(cause){if(current===generation)error.value=cause instanceof Error?cause.message:'设置保存失败';}finally{if(current===generation)busy.value=false;}}
async function loadRecent(page=1){const current=generation;try{const result=await api.fetchAdmissionCollections(page);if(current===generation&&!disposed)recent.value=result;}catch(cause){if(current===generation)notice.value=cause instanceof Error?cause.message:'最近批次读取失败';}}
async function readItems(batch:AdmissionCollection['batches'][number],current:number){const items:AdmissionItem[]=[];let page=1,total=Infinity;while(items.length<total){const result=await api.fetchAdmissionItems(batch.id,page++,100);if(current!==generation||disposed)return;items.push(...result.items);total=result.total;if(!result.items.length)break;}if(current!==generation||disposed)return;const previous=contexts[batch.id];const context:BatchContext={batch,items,actions:previous?.actions??{},works:previous?.works??{}};for(const item of items){if(context.actions[item.key])continue;const suggested=batch.state==='draft'?item.suggestedAction:undefined,work=suggested?.action==='existing'?item.candidates.find(work=>work.workId===suggested.workId):undefined;context.actions[item.key]=suggested&&(suggested.action!=='existing'||work)?{...suggested,key:item.key,approvedAds:[...(suggested.approvedAds??[])],acceptSourceIds:[...(suggested.acceptSourceIds??[])]}:admissionAction(item,'defer');if(work)context.works[item.key]=work;}contexts[batch.id]=context;}
async function readAllItems(batches:AdmissionCollection['batches'],current:number){itemsLoading.value=true;try{let index=0;const worker=async()=>{while(index<batches.length&&current===generation&&!disposed){const batch=batches[index++];await readItems(batch,current);}};await Promise.all([worker(),worker()]);}finally{if(current===generation)itemsLoading.value=false;}}
function stopPoll(){if(timer)clearTimeout(timer);timer=undefined;}
function schedulePoll(){stopPoll();if(active.value&&!disposed&&pollFailures<3&&!document.hidden)timer=setTimeout(()=>void refreshCollection(true),2500);}
async function openCollection(id:string){
  saveDraft();const current=++generation;busy.value=false;stopPoll();collection.value=null;pending.value=null;showConfirm.value=false;showResume.value=false;confirmed.value=false;adsConfirmed.value=false;error.value='';page.value=1;group.value='all';for(const key of Object.keys(contexts))delete contexts[key];
  try {
    const result=await api.fetchAdmissionCollection(id);if(current!==generation||disposed)return;
    collection.value=result;activeBatchId.value=result.batches[0]?.id??'';
    await readAllItems(result.batches,current);if(current!==generation||disposed)return;
    if(result.state==='draft'){
      const restored=restoreAdmissionDraft(id,draftEntries());
      for(const entry of restored){contexts[entry.batchId].actions[entry.key]=entry.action;if(entry.work)contexts[entry.batchId].works[entry.key]=entry.work;}
      restorePending();
      if(!pending.value)selectSafe(new Set(restored.map(entry=>`${entry.batchId}:${entry.key}`)));
    }else {setPending(null);clearAdmissionDraft(id);}
    rememberAdmissionCollection(id);saveDraft();
    await router.replace({query:{collection:id}});pollFailures=0;schedulePoll();
  }catch(cause){
    if(current!==generation||disposed)return;
    collection.value=null;
    if(cause instanceof RequestError&&[403,404].includes(cause.status)){if(lastAdmissionCollection()===id)rememberAdmissionCollection(null);clearAdmissionDraft(id);}
    await loadWorkspace();if(current===generation&&!disposed)error.value=cause instanceof Error?cause.message:'批次读取失败';
  }
}
async function refreshCollection(poll=false){if(!collection.value)return;saveDraft();const current=generation,id=collection.value.id;try{const result=await api.fetchAdmissionCollection(id);if(current!==generation||disposed)return;const changed=result.batches.filter(batch=>{const old=contexts[batch.id]?.batch;return !poll||!old||old.state!==batch.state||old.updatedAt!==batch.updatedAt||old.totals.completed!==batch.totals.completed;});collection.value=result;if(result.state!=='draft')setPending(null);await readAllItems(changed,current);if(current!==generation||disposed)return;pollFailures=0;schedulePoll();}catch(cause){if(current!==generation)return;pollFailures++;if(!poll||pollFailures>=3)error.value=cause instanceof Error?cause.message:'状态读取失败';schedulePoll();}}
async function preview(){if(busy.value||scopeError.value||!directoryCount.value)return;let current=generation;busy.value=true;error.value='';try{const scopes=chosenFolders.value.map(([parent,value])=>({creatorId:value.creator!.id,parent,directories:[...value.directories],acceptExistingVersion:true,...(value.sourceEvidenceId?{sourceEvidenceId:value.sourceEvidenceId}:{})}));const result=await api.previewAdmissionCollection(scopes);if(current!==generation||disposed)return;current++;await openCollection(result.id);if(current===generation&&!disposed)await loadRecent();}catch(cause){if(current===generation&&!disposed)error.value=cause instanceof Error?cause.message:'预览失败';}finally{if(current===generation&&!disposed)busy.value=false;}}
function selectSafe(restored?:Set<string>){
  if(locked.value)return;
  for(const context of Object.values(contexts))for(const item of context.items){
    if(restored&&(restored.has(`${context.batch.id}:${item.key}`)||item.suggestedAction))continue;
    if(item.group==='A'&&!item.candidates.length&&!item.conflicts.length&&!item.structureWarnings?.length&&!item.needsBoundaryReview&&context.actions[item.key]?.action==='defer')
      context.actions[item.key]={...admissionAction(item,'new',context.actions[item.key]),reason:restored?'首次核对预选无冲突的新作品，待用户最终确认':'用户补选当前预览中无冲突的新作品'};
  }
  adsConfirmed.value=false;saveDraft();
}
async function execute(){if(!collection.value||busy.value||selectionError.value)return;saveDraft();const current=generation,id=collection.value.id;busy.value=true;error.value='';try{const input:AdmissionCollectionExecuteInput=pending.value??{requestKey:crypto.randomUUID(),confirmed:true,batches:collection.value.batches.map(batch=>{const entries=entriesFor(contexts[batch.id]);return {batchId:batch.id,acceptExistingVersion:true,actions:admissionPayload(entries,true),...(entries.some(entry=>isAdmissionSelected(entry.action)&&entry.action.approvedAds?.length)?{adsConfirmed:true as const}:{})};})};setPending(input);const result=await api.executeAdmissionCollection(id,input);if(current!==generation||disposed)return;collection.value=result;setPending(null);showConfirm.value=false;await readAllItems(result.batches,current);schedulePoll();await loadRecent();}catch(cause){if(current!==generation||disposed)return;error.value=cause instanceof RequestError&&cause.status===413?'本批确认内容超过上限，请分小批；服务端未接受本次执行。':cause instanceof Error?cause.message:'回执未确认';if(definitive(cause))setPending(null);}finally{if(current===generation&&!disposed)busy.value=false;}}
async function resume(){if(!collection.value||busy.value)return;const current=generation,id=collection.value.id,key=`${storageKey(id)}:resume`;busy.value=true;error.value='';let requestKey:string;try{requestKey=localStorage.getItem(key)||crypto.randomUUID();localStorage.setItem(key,requestKey);}catch{requestKey=crypto.randomUUID();}try{const result=await api.resumeAdmissionCollection(id,{requestKey,confirmed:true});try{localStorage.removeItem(key);}catch{/* Server receipt persists. */}if(current!==generation||disposed)return;collection.value=result;showResume.value=false;pollFailures=0;schedulePoll();}catch(cause){if(definitive(cause))try{localStorage.removeItem(key);}catch{/* Rejected receipt is not pending. */}if(current===generation)error.value=cause instanceof Error?cause.message:'继续失败';}finally{if(current===generation&&!disposed)busy.value=false;}}
async function startNew(){
  saveDraft();generation++;stopPoll();rememberAdmissionCollection(null);collection.value=null;pending.value=null;showConfirm.value=false;showResume.value=false;confirmed.value=false;adsConfirmed.value=false;error.value='';startingNew=true;
  for(const key of Object.keys(contexts))delete contexts[key];
  try {await router.replace({query:{}});await loadWorkspace();}finally{startingNew=false;}
}
function visible(){if(document.hidden)stopPoll();else schedulePoll();}
watch(group,()=>page.value=1);
watch(()=>route.query.collection,async id=>{
  if(typeof id==='string'){if(id!==collection.value?.id)await openCollection(id);}
  else if(id===undefined){
    if(startingNew)return;
    const remembered=lastAdmissionCollection();
    if(remembered){if(remembered!==collection.value?.id)await openCollection(remembered);else await router.replace({query:{collection:remembered}});}
    else if(collection.value)await startNew();
    else if(!workspace.value)await loadWorkspace();
  }
},{immediate:true});
void loadRecent();document.addEventListener('visibilitychange',visible);window.addEventListener('pagehide',saveDraft);
onBeforeUnmount(()=>{saveDraft();disposed=true;generation++;stopPoll();document.removeEventListener('visibilitychange',visible);window.removeEventListener('pagehide',saveDraft);});
</script>

